files.model/model_selection.py:
"""Explicit native model selections and their retained source/output requirements."""
from __future__ import annotations

from .common import (MODELS as MODEL_ORDER, MODEL_ROLES,
                     MODEL_OUTPUTS as NATIVE_OUTPUTS, selected_models,
                     required_roles as native_required_roles)

MODEL_LABELS = {"ndr": "Nutrient Delivery Ratio", "sdr": "Sediment Delivery Ratio"}
MODEL_OUTPUTS = {
    model: tuple(name for name, native in NATIVE_OUTPUTS.items() if native[0] == model)
    for model in MODEL_ORDER
}
OUTPUT_ORDER = tuple(NATIVE_OUTPUTS)
TABLE_FIELDS = {
    "ndr": ("lucode", "load_n", "load_p", "load_type_n", "load_type_p",
            "eff_n", "eff_p", "crit_len_n", "crit_len_p", "proportion_subsurface_n"),
    "sdr": ("lucode", "usle_c", "usle_p"),
}


def models(value=None, *, default=MODEL_ORDER):
    """Use the same model normalization as the maintained regional programme."""
    if value is None:
        value = list(default)
    return tuple(selected_models(value))


def selected(record, *, default=MODEL_ORDER):
    if not isinstance(record, dict):
        raise ValueError("Retain the complete native model selection")
    return models(record if "models" in record else None, default=default)


def normalize_selection(record, *, default=MODEL_ORDER):
    """Keep the historical complete-model identity when both models are selected."""
    result = dict(record)
    names = selected(result, default=default)
    if names == MODEL_ORDER:
        result.pop("models", None)
    else:
        result["models"] = list(names)
    return result, names


def required_roles(selection=None):
    return native_required_roles(models(selection))


def required_outputs(selection=None):
    wanted = set().union(*(MODEL_OUTPUTS[name] for name in models(selection)))
    return tuple(name for name in OUTPUT_ORDER if name in wanted)


def required_table_fields(selection=None):
    result = []
    for model in models(selection):
        for name in TABLE_FIELDS[model]:
            if name not in result:
                result.append(name)
    return tuple(result)


def grid_models(grid):
    return selected(grid["spec"])


def run_models(run):
    return selected(run["selection"])


def run_scope(run):
    selected_models = run_models(run)
    expected = required_outputs(selected_models)
    present = tuple(name for name in expected if name in run.get("artifacts", {}))
    completed = tuple(name for name in selected_models
                      if name in run.get("stages", {})
                      and all(item in present for item in MODEL_OUTPUTS[name]))
    return {
        "selected_models": list(selected_models),
        "native_stages_complete": [name for name in selected_models
                                   if run.get("stages", {}).get(name, {}).get("completed_at")],
        "completed_models": list(completed),
        "omitted_models": [name for name in MODEL_ORDER if name not in selected_models],
        "expected_artifacts": list(expected),
        "available_artifacts": list(present),
        "selected_models_complete": run.get("state") == "complete" and completed == selected_models,
        "full_model_outputs": run.get("state") == "complete" and completed == MODEL_ORDER,
    }


def validate_completed_run(run):
    scope = run_scope(run)
    if run.get("state") == "complete" and not scope["selected_models_complete"]:
        raise ValueError("Completed run lacks one of its selected native stages or original exports")
    return scope


def common_comparison_outputs(runs):
    if not runs:
        raise ValueError("Choose completed native model runs")
    available = set(OUTPUT_ORDER)
    for run in runs:
        scope = validate_completed_run(run)
        if not scope["selected_models_complete"]:
            raise ValueError("Finish the models selected for every compared run")
        available.intersection_update(scope["expected_artifacts"])
    if not available:
        raise ValueError("Compared runs must include at least one common native model")
    return tuple(name for name in OUTPUT_ORDER if name in available)


def require_complete_delivery(run):
    scope = validate_completed_run(run)
    if not scope["full_model_outputs"]:
        missing = [MODEL_LABELS[name] for name in MODEL_ORDER
                   if name not in scope["completed_models"]]
        raise ValueError("The complete seven-family delivery requires both native models. "
                         "Complete " + ", ".join(missing)
                         + " on the selected common grid/profile; retained selected-model "
                         "runs remain available in this workspace.")
    return scope

files.model/profiles.py:
"""Preserve actual biophysical tables and explicit native algorithm parameters."""
from __future__ import annotations
import csv
import io
from .common import finite
from .model_selection import models as normalize_models, required_table_fields, selected

NDR_KEYS = {"threshold_flow_accumulation", "k_param", "flow_dir_algorithm",
            "subsurface_critical_length_n", "subsurface_eff_n", "runoff_proxy_av"}
SDR_KEYS = {"threshold_flow_accumulation", "k_param", "flow_dir_algorithm",
            "sdr_max", "ic_0_param", "l_max"}
TABLE_FIELDS = ("lucode", "load_n", "load_p", "load_type_n", "load_type_p",
                "eff_n", "eff_p", "crit_len_n", "crit_len_p",
                "proportion_subsurface_n", "usle_c", "usle_p")

def inspect_table(path, models=None, *, selected_models=None):
    if models is not None and selected_models is not None and normalize_models(models) != normalize_models(selected_models):
        raise ValueError("The two model selections for the original table differ")
    active = normalize_models(selected_models if selected_models is not None else models)
    required = required_table_fields(active)
    with open(path, encoding="utf-8-sig", newline="") as f:
        reader = csv.DictReader(f)
        fields = reader.fieldnames or []
        missing = sorted(set(required) - set(fields))
        if missing:
            raise ValueError("Biophysical CSV requires columns: " + ", ".join(missing))
        rows, seen = [], set()
        for line, row in enumerate(reader, 2):
            token = row["lucode"].strip()
            try:
                code = int(token)
            except ValueError as exc:
                raise ValueError("CSV line " + str(line) + " has a noninteger lucode") from exc
            if code in seen:
                raise ValueError("Duplicate biophysical lucode: " + str(code))
            seen.add(code)
            for name in ("load_n", "load_p", "eff_n", "eff_p", "crit_len_n",
                         "crit_len_p", "proportion_subsurface_n", "usle_c", "usle_p"):
                if name not in required:
                    continue
                x = finite(row[name], name, minimum=0)
                if name in ("eff_n", "eff_p", "proportion_subsurface_n", "usle_c", "usle_p") and x > 1:
                    raise ValueError(name + " must be between zero and one")
                if name in ("crit_len_n", "crit_len_p") and x <= 0:
                    raise ValueError(name + " must be positive")
            for name in ("load_type_n", "load_type_p"):
                if name not in required:
                    continue
                if row[name].strip() not in ("application-rate", "measured-runoff"):
                    raise ValueError(name + " must state application-rate or measured-runoff")
            rows.append(row)
    if not rows:
        raise ValueError("The biophysical CSV is empty")
    return {"columns": fields, "rows": rows, "lucodes": sorted(seen)}

def checked_parameters(profile):
    if not isinstance(profile.get("title"), str) or not profile["title"].strip():
        raise ValueError("Name the parameter profile")
    if not profile.get("references"):
        raise ValueError("Supply the source references for this parameter profile")
    result = {}
    active = selected(profile)
    for model, allowed, optional in (("ndr", NDR_KEYS, {"runoff_proxy_av"}),
                                     ("sdr", SDR_KEYS, set())):
        if model not in active:
            continue
        values = profile.get(model, {})
        if not isinstance(values, dict):
            raise ValueError(model.upper() + " parameters must be an object")
        if set(values) - allowed:
            raise ValueError("Unsupported " + model + " parameters: " + ", ".join(sorted(set(values) - allowed)))
        missing = allowed - optional - set(values)
        if missing:
            raise ValueError("Supply " + model + " parameters: " + ", ".join(sorted(missing)))
        out = dict(values)
        if out["flow_dir_algorithm"] not in ("mfd", "d8"):
            raise ValueError("Native flow_dir_algorithm must be mfd or d8")
        for name in allowed - {"flow_dir_algorithm"}:
            if name not in out:
                continue
            positive = name in ("threshold_flow_accumulation", "k_param",
                                "subsurface_critical_length_n", "l_max", "runoff_proxy_av")
            out[name] = finite(out[name], model + "." + name, positive=positive)
        for name in ("subsurface_eff_n", "sdr_max"):
            if name in out and not 0 <= out[name] <= 1:
                raise ValueError(model + "." + name + " must be between zero and one")
        result[model] = out
    return result

def scenario_spec(value):
    if not value.get("title") or not value.get("reason"):
        raise ValueError("Name the scenario and explain the actual land-cover assumptions")
    kind = value.get("kind")
    if kind not in ("baseline", "landcover"):
        raise ValueError("Scenario kind must be baseline or landcover")
    patches = value.get("patches", [])
    if kind == "baseline" and patches:
        raise ValueError("The baseline uses the original land-cover edition")
    if kind == "landcover" and not patches:
        raise ValueError("Add the actual proposed land-cover changes")
    for patch in patches:
        if not patch.get("mask_source_id"):
            raise ValueError("Select a retained vector source for each scenario area")
        if type(patch.get("to_code")) is not int:
            raise ValueError("Each scenario destination must be an integer land-cover code")
        if not isinstance(patch.get("from_codes"), list) or not patch["from_codes"] or any(type(x) is not int for x in patch["from_codes"]):
            raise ValueError("List the original land-cover codes affected by each change")
        if not patch.get("reason"):
            raise ValueError("Explain each mapped land-cover change")
    return value

files.model/reuse.py:
"""Reuse original completed files without altering either retained operation."""
from __future__ import annotations
import os
from pathlib import Path
import shutil
import tempfile
from .common import describe_file, file_digest, relative_file, verify_file


def destination_file(root, relative):
    root = Path(root).resolve()
    member = Path(relative)
    if (not isinstance(relative, str) or not member.parts or member.is_absolute()
            or ".." in member.parts or "\\" in relative or "\0" in relative
            or member.as_posix() != relative):
        raise ValueError("Retained reuse requires a portable relative file name")
    target = root / member
    if target.is_symlink() or not target.resolve().is_relative_to(root):
        raise ValueError("Retained reuse destination escapes its operation")
    return target


def copy_verified(source_root, descriptor, destination_root, *, path=None):
    """Hardlink or copy a complete original, checking both actual file bodies."""
    source = verify_file(source_root, descriptor)
    relative = descriptor["path"] if path is None else path
    target = destination_file(destination_root, relative)
    target.parent.mkdir(parents=True, exist_ok=True)
    expected = {**descriptor, "path": relative}
    if target.exists():
        verify_file(destination_root, expected)
        return expected
    try:
        os.link(source, target)
    except FileExistsError:
        pass
    except OSError:
        pending = None
        try:
            with source.open("rb") as src, tempfile.NamedTemporaryFile(
                    dir=target.parent, prefix=".reuse-", delete=False) as out:
                pending = Path(out.name)
                shutil.copyfileobj(src, out, 1024 * 1024)
                out.flush()
                os.fsync(out.fileno())
            if (pending.stat().st_size != descriptor["bytes"]
                    or file_digest(pending) != descriptor["sha256"]):
                raise ValueError("Original retained file changed during reuse")
            try:
                os.link(pending, target)
            except FileExistsError:
                pass
        finally:
            if pending is not None:
                pending.unlink(missing_ok=True)
    verify_file(destination_root, expected)
    return expected


def native_companions(directory, files):
    """Preserve native Shapefile components and raster auxiliary/mask files."""
    result = {}
    claimed = {item["path"] for item in files.values()}
    for item in files.values():
        path = relative_file(directory, item["path"])
        suffix = path.suffix.lower()
        candidates = []
        if suffix == ".shp":
            candidates.extend(path.parent.glob(path.stem + ".*"))
        elif suffix in (".tif", ".tiff"):
            candidates.extend(Path(str(path) + tail) for tail in (".aux.xml", ".msk", ".ovr"))
        for companion in candidates:
            if not companion.is_file():
                continue
            descriptor = describe_file(directory, companion)
            if descriptor["path"] not in claimed:
                result[descriptor["path"]] = descriptor
    return [result[name] for name in sorted(result)]


def verify_stage(directory, stage):
    if not isinstance(stage, dict) or not stage.get("completed_at"):
        raise ValueError("Retain the completed original native stage")
    verify_file(directory, stage["arguments"])
    for item in stage["files"].values():
        verify_file(directory, item)
    for item in stage.get("companions", []):
        verify_file(directory, item)
    if stage.get("requested_arguments"):
        verify_file(directory, stage["requested_arguments"])
    return stage

files.model/grid_reuse.py:
"""Extend a retained model grid using its exact original common preparations."""
from __future__ import annotations
from .common import digest
from .model_selection import required_roles
from .reuse import copy_verified, native_companions


def source_identity(workspace, collection_id, source_id):
    _, entry = workspace.source_file(collection_id, source_id)
    def body(value):
        return {"bytes": value["bytes"], "sha256": value["sha256"],
                "view_path": value.get("view_path", value["filename"])}
    return {
        "kind": entry["kind"], "body": body(entry["body"]),
        "companions": sorted((body(value) for value in entry["companions"]),
                             key=lambda value: value["view_path"]),
        "layer": entry.get("layer"), "units": entry.get("units"),
        "conversion": entry.get("conversion"), "resampling": entry.get("resampling"),
    }


def geometry_identity(workspace, spec, name):
    selection = spec[name]
    return {"source": source_identity(workspace, spec["source_collection_id"],
                                      selection["source_id"]),
            "layer": selection.get("layer"),
            "where": selection.get("where")}


def reuse_grid_inputs(workspace, state, directory, selected_models):
    """Return the same state with byte-identical available inputs carried forward.

    Selecting base_grid_id is explicit. A different source/filter, model domain,
    reporting area, buffer or grid cannot silently inherit the older preparation.
    The source collection itself may be a new edition containing added inputs.
    """
    spec = state["spec"]
    base_id = spec.get("base_grid_id")
    if not base_id:
        return state
    if base_id == state["id"]:
        raise ValueError("A grid cannot extend itself")
    original = workspace.get_grid(base_id)
    old_spec = original["spec"]
    if (digest(original["grid"]) != digest(state["grid"])
            or float(old_spec["upstream_buffer_m"]) != float(spec["upstream_buffer_m"])):
        raise ValueError("Grid extension requires the original exact grid and context buffer")
    for name in ("reporting_area", "model_domain"):
        if digest(geometry_identity(workspace, old_spec, name)) != digest(
                geometry_identity(workspace, spec, name)):
            raise ValueError("Grid extension changes the original " + name + " source selection")
    old_directory = workspace.root / "grids" / base_id
    reused = dict(state.get("reused_inputs", {}))
    for name in ("model_domain", "reporting_area", "reporting_mask"):
        if name not in original["files"]:
            raise ValueError("Original grid lacks its complete " + name)
        if name not in state["files"]:
            state["files"][name] = copy_verified(old_directory, original["files"][name], directory)
            reused[name] = {"grid_id": base_id, "path": original["files"][name]["path"],
                            "sha256": original["files"][name]["sha256"]}
    for role in required_roles(selected_models):
        if role in state["files"] or role not in original["files"]:
            continue
        old_source = old_spec["input_sources"].get(role)
        new_source = spec["input_sources"].get(role)
        if old_source is None or new_source is None:
            continue
        old_identity = source_identity(workspace, old_spec["source_collection_id"], old_source)
        new_identity = source_identity(workspace, spec["source_collection_id"], new_source)
        if digest(old_identity) != digest(new_identity):
            continue
        state["files"][role] = copy_verified(old_directory, original["files"][role], directory)
        companions = native_companions(old_directory, {role: original["files"][role]})
        if companions:
            state.setdefault("input_companions", {})[role] = [
                copy_verified(old_directory, item, directory) for item in companions]
        _, entry = workspace.source_file(spec["source_collection_id"], new_source)
        state["inputs"][role] = {
            **original["inputs"][role], "source_id": entry["id"],
            "source_sha256": entry["body"]["sha256"], "source_uri": entry["uri"],
            "vintage": entry["vintage"], "reused_from_grid": base_id,
            "original_source_collection_id": old_spec["source_collection_id"],
            "original_source_id": old_source,
        }
        reused[role] = {"grid_id": base_id, "path": original["files"][role]["path"],
                        "sha256": original["files"][role]["sha256"]}
    state["reused_inputs"] = reused
    return state

files.model/stage_cache.py:
"""Content-selected reuse of original native stages within this workspace."""
from __future__ import annotations
import importlib.metadata
import platform
from pathlib import Path
import sys
from .common import atomic_json, describe_file, digest, file_digest, identifier, now, read_json
from .model_selection import run_models
from .reuse import copy_verified, destination_file, native_companions, verify_stage

INPUT_PATHS = {
    "ndr": ("dem_path", "lulc_path", "watersheds_path", "biophysical_table_path", "runoff_proxy_path"),
    "sdr": ("dem_path", "lulc_path", "watersheds_path", "biophysical_table_path",
            "erosivity_path", "erodibility_path", "drainage_path"),
}


def runtime_environment():
    """Record the actual native environment used for an exact-stage match."""
    result = {"python": list(sys.version_info[:3]), "implementation": platform.python_implementation(),
              "system": platform.system(), "machine": platform.machine(), "packages": {}}
    for package in ("natcap.invest", "numpy", "scipy", "pygeoprocessing",
                    "taskgraph", "GDAL", "shapely", "pandas", "pint"):
        try:
            result["packages"][package] = importlib.metadata.version(package)
        except importlib.metadata.PackageNotFoundError:
            result["packages"][package] = None
    try:
        from osgeo import gdal
        result["gdal"] = gdal.VersionInfo("--version")
    except ImportError:
        result["gdal"] = None
    return result


def signature(model, arguments, runtime_source, *, verified_inputs=None):
    if model not in INPUT_PATHS:
        raise ValueError("Select a published native model")
    values = {key: value for key, value in arguments.items()
              if key not in ("workspace_dir",) + INPUT_PATHS[model]}
    inputs = {}
    for name in INPUT_PATHS[model]:
        selected_path = arguments.get(name)
        if selected_path in (None, ""):
            inputs[name] = None
            continue
        path = Path(selected_path).resolve(strict=True)
        if not path.is_file():
            raise ValueError("Native stage input is not an original regular file: " + name)
        retained = (verified_inputs or {}).get(str(path))
        if retained is not None:
            if path.stat().st_size != retained["bytes"]:
                raise ValueError("Verified native input length changed: " + name)
            inputs[name] = {"bytes": retained["bytes"], "sha256": retained["sha256"]}
        else:
            inputs[name] = {"bytes": path.stat().st_size, "sha256": file_digest(path)}
        companions = []
        suffix = path.suffix.lower()
        if suffix == ".shp":
            candidates = [item for item in path.parent.glob(path.stem + ".*") if item != path]
        elif suffix in (".tif", ".tiff"):
            candidates = [Path(str(path) + tail) for tail in (".aux.xml", ".msk", ".ovr")]
        else:
            candidates = []
        for companion in sorted(candidates):
            if companion.is_file():
                companions.append({"name": companion.name, "bytes": companion.stat().st_size,
                                   "sha256": file_digest(companion)})
        if companions:
            inputs[name]["companions"] = companions
    dependencies = ("ndr", "sdr") if model == "ndr" else ("sdr",)
    modules = {name: runtime_source["modules"][name] for name in dependencies}
    selection = {"schema": "upstate.native-stage-inputs/v1", "model": model,
                 "invest_version": runtime_source["version"], "modules": modules,
                 "environment": runtime_source["environment"], "arguments": values, "inputs": inputs}
    return {"id": digest(selection), "selection": selection}


def register(workspace, run_id, model, stage):
    selected = stage.get("input_signature")
    if not selected:
        return
    if digest(selected["selection"]) != selected["id"]:
        raise ValueError("Native stage input identity differs")
    run_id = identifier(run_id)
    key = identifier(selected["id"])
    record = {"schema": "upstate.native-stage-cache/v1", "id": key,
              "run_id": run_id, "model": model, "completed_at": stage["completed_at"]}
    atomic_json(workspace.root / "stage-cache" / key / (run_id + "-" + model + ".json"),
                record, immutable=True)


def _check_destinations(directory, files):
    seen = {}
    for item in files:
        path = item["path"]
        if path in seen and (seen[path]["bytes"], seen[path]["sha256"]) != (item["bytes"], item["sha256"]):
            raise ValueError("Native reuse has conflicting original output paths")
        seen[path] = item
        target = destination_file(directory, path)
        if target.exists():
            from .common import verify_file
            verify_file(directory, item)


def recover(workspace, run_id, model, selected, directory, requested_arguments):
    """Return an original matching stage, or None; malformed candidates stay explicit.

    Only completed stages recorded by this adapter are indexed. A surviving stage
    in a later failed run remains useful. Every retained body is checked before
    it is linked/copied; unindexed historical runs remain readable normally.
    """
    folder = workspace.root / "stage-cache" / identifier(selected["id"])
    observations = []
    candidates = sorted(folder.glob("*-" + model + ".json")) if folder.exists() else []
    for path in candidates:
        try:
            record = read_json(path)
            if (record.get("schema") != "upstate.native-stage-cache/v1"
                    or record.get("id") != selected["id"] or record.get("model") != model):
                raise ValueError("Native reuse index differs")
            original_id = identifier(record["run_id"])
            if original_id == run_id:
                continue
            original = workspace.inspect_run(original_id)
            if model not in run_models(original):
                raise ValueError("Original run did not select this native model")
            stage = original["stages"][model]
            if stage.get("input_signature") != selected:
                raise ValueError("Original stage inputs differ")
            old_directory = workspace.root / "runs" / original_id
            verify_stage(old_directory, stage)
            companions = native_companions(old_directory, stage["files"])
            by_path = {item["path"]: item for item in stage.get("companions", [])}
            by_path.update({item["path"]: item for item in companions})
            companions = [by_path[name] for name in sorted(by_path)]
            output_files = list(stage["files"].values()) + companions
            original_arguments = {**stage["arguments"], "path": model + "-source-arguments.json"}
            _check_destinations(directory, output_files + [original_arguments])
        except (OSError, ValueError, KeyError, TypeError) as exc:
            observations.append({"index": path.relative_to(workspace.root).as_posix(),
                                 "reason": str(exc)})
            continue
        # Mutation starts only after the full original candidate and all existing
        # destinations have been checked. Any I/O failure leaves this same run
        # resumable, with no unrelated original or output replaced.
        files = {name: copy_verified(old_directory, item, directory)
                 for name, item in stage["files"].items()}
        copied_companions = [copy_verified(old_directory, item, directory) for item in companions]
        source_arguments = copy_verified(old_directory, stage["arguments"], directory,
                                         path=original_arguments["path"])
        request_path = directory / (model + "-arguments.json")
        atomic_json(request_path, requested_arguments)
        result = {
            **stage, "arguments": source_arguments, "files": files,
            "companions": copied_companions,
            "requested_arguments": describe_file(directory, request_path),
            "input_signature": selected,
            "reused_at": now(),
            "reused_from": {
                "run_id": original_id, "model": model,
                "stage_completed_at": stage["completed_at"],
                "input_signature": selected["id"],
                "original_arguments": stage["arguments"],
                "previous_reuse": stage.get("reused_from"),
            },
        }
        return result, observations
    return None, observations

