.observation-plot{margin:20px auto;max-width:620px}.observation-plot svg{display:block;width:100%;height:auto;font:11px system-ui,sans-serif;background:#fff}.observation-plot figcaption{font-size:12px;line-height:1.55;color:#555;margin-top:10px}.row-detail{margin-top:6px;max-width:350px}.row-detail summary{font-size:12px;cursor:pointer}.row-detail pre{font-size:11px;max-height:220px;max-width:330px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;padding:8px;background:#f4f4f4}.observation-plot circle:focus{stroke:#000;stroke-width:2;outline:none}

/* Model selectors keep the existing industrial forms and keyboard order. */
[data-native-models][hidden]{display:none!important}

/* Spatial review uses the existing neutral workbench palette. */
.spatial-workbench{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:16px;align-items:start}
.spatial-map-area{min-width:0;background:var(--paper);border:1px solid var(--line);border-radius:4px;overflow:hidden}
.spatial-source-controls{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;padding:14px;border-bottom:1px solid var(--line);background:#f7f8f9}
.spatial-field{display:block;min-width:0;margin:0;font-size:12px;font-weight:600}
.spatial-field>input,.spatial-field>select,.spatial-field>textarea{display:block;width:100%;margin-top:5px;padding:7px 8px;min-height:34px;font-size:12px}
.spatial-field>small{font-weight:400;color:var(--muted);margin-top:5px}
.spatial-tools{display:flex;gap:10px;align-items:center;flex-wrap:wrap;padding:10px 12px;border-bottom:1px solid var(--line)}
.spatial-tool-group{display:flex;gap:4px}.spatial-tools button{padding:6px 8px;font-size:12px}
.spatial-tools button[aria-pressed=true]{background:#262c32;color:#fff;border-color:#262c32}
.spatial-coordinate{margin-left:auto;color:#505963;font:11px ui-monospace,SFMono-Regular,Consolas,monospace;font-variant-numeric:tabular-nums}
.spatial-canvases{display:grid;grid-template-columns:minmax(0,1fr);gap:12px;padding:12px;min-width:0;background:#e9ecef}
.spatial-canvases.spatial-linked{grid-template-columns:repeat(2,minmax(0,1fr))}
.spatial-pane{min-width:0;border:1px solid #aab2bb;background:#fff}
.spatial-pane>header{display:flex;justify-content:space-between;gap:8px;min-height:34px;padding:8px 10px;border-bottom:1px solid #bfc6cd;font-size:11px;line-height:1.35}
.spatial-pane>header strong{overflow-wrap:anywhere}.spatial-pane>header span{flex-shrink:0;color:var(--muted)}
.spatial-map{position:relative;width:100%;overflow:hidden;touch-action:none;user-select:none;isolation:isolate;background-color:#f9f9f9;background-image:linear-gradient(45deg,#e2e2e2 25%,transparent 25%),linear-gradient(-45deg,#e2e2e2 25%,transparent 25%),linear-gradient(45deg,transparent 75%,#e2e2e2 75%),linear-gradient(-45deg,transparent 75%,#e2e2e2 75%);background-size:16px 16px;background-position:0 0,0 8px,8px -8px,-8px 0}
.spatial-map:focus-visible{outline:3px solid #333;outline-offset:-3px}
.spatial-map[data-tool=pan]{cursor:grab}.spatial-map[data-tool=pan]:active{cursor:grabbing}.spatial-map[data-tool=inspect],.spatial-map[data-tool=mark]{cursor:crosshair}
.spatial-raster,.spatial-vector-canvas,.spatial-swipe-image{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}
.spatial-raster{image-rendering:pixelated;object-fit:fill}.spatial-swipe-image{overflow:hidden}.spatial-vector-canvas{z-index:2}
.spatial-map-axis{position:absolute;right:7px;top:7px;z-index:3;padding:2px 5px;background:rgba(255,255,255,.85);border:1px solid #777;font-size:10px;pointer-events:none}
.spatial-map-empty{min-height:350px;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center;gap:10px;padding:35px;color:#59636e;background:#fafbfc}
.spatial-map-empty h2{color:var(--ink);font-size:18px}.spatial-map-empty p{max-width:540px}
.spatial-swipe-control{padding:10px 16px;border-bottom:1px solid var(--line)}
.spatial-swipe-control input[type=range]{padding:0;min-height:24px;accent-color:#3a3a3a}
.spatial-map-footer{padding:12px 14px;border-top:1px solid var(--line);font-size:12px;background:#fff}
.spatial-map-footer [data-spatial-status]{margin-top:8px;color:#505a64}
.spatial-legend-item{display:flex;flex-wrap:wrap;gap:7px;align-items:center;margin-bottom:5px;font-variant-numeric:tabular-nums}
.spatial-legend-item small{flex-basis:100%;padding-left:78px;font-size:10px}
.spatial-ramp{display:inline-block;width:70px;height:10px;border:1px solid #777;background:linear-gradient(to right,#1c1c1c,#e8e8e8)}
.spatial-nodata-key{font-size:10px;color:var(--muted)}
.spatial-view-meta{display:flex;flex-wrap:wrap;gap:5px 16px;padding:10px 14px;font-size:10px;color:#59636d;border-top:1px solid var(--line);overflow-wrap:anywhere}
.spatial-view-meta details{width:100%}.spatial-view-meta details>p{margin-top:5px}.spatial-view-meta summary{cursor:pointer}
.spatial-warning,.spatial-fit-confirm{padding:12px 14px;background:#f0f0f0;border-top:1px solid #b7b7b7;border-bottom:1px solid #b7b7b7;font-size:12px}
.spatial-fit-confirm button{margin:9px 6px 0 0;font-size:12px}
.spatial-inspector{padding:16px;border-top:1px solid var(--line)}
.spatial-inspector>header{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:12px}
.spatial-inspector h2{font-size:15px}.spatial-inspector h3{font-size:12px;margin-bottom:8px}.spatial-inspector button{font-size:11px;padding:5px 8px}
.spatial-inspection-location{font-size:11px;overflow-wrap:anywhere;margin-bottom:12px}
.spatial-pixel-columns{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px}
.spatial-pixel-columns section{min-width:0;border:1px solid var(--line);background:#fbfcfd;padding:12px}
.spatial-inspector dl{display:grid;grid-template-columns:minmax(80px,.8fr) minmax(0,1.3fr);gap:6px 12px;margin:0 0 10px;font-size:11px}
.spatial-inspector dt{color:#59636e}.spatial-inspector dd{margin:0;overflow-wrap:anywhere;font-variant-numeric:tabular-nums}
.spatial-difference-value{border:1px solid #aaa;padding:10px 12px;margin-top:12px;font-size:12px}
